const svg=body=>`<svg viewBox="0 0 180 110" role="img" aria-label="음표 모양">${body}</svg>`;
const head=(x,y,filled)=>`<ellipse cx="${x}" cy="${y}" rx="15" ry="10" transform="rotate(-20 ${x} ${y})" fill="${filled?'currentColor':'none'}" stroke="currentColor" stroke-width="4"/>`;
const note=(filled,flag=false)=>svg(head(77,79,filled)+`<path d="M90 77V21${flag?' Q122 31 106 54':''}" fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="round"/>`);
export const MUSIC_QUIZ=Object.freeze([
{id:'quarter',kind:'quarter',symbol:note(true),question:'속이 찬 머리와 기둥. 어떤 음표일까요?',choices:['4분음표','2분음표','온음표'],answer:0,why:'4분음표예요. 이 퀴즈에서는 4분음표를 한 박으로 세어요.'},
{id:'half',kind:'half',symbol:note(false),question:'속이 빈 머리에 기둥이 있어요. 몇 박일까요?',choices:['한 박','두 박','네 박'],answer:1,why:'2분음표는 4분음표 두 개만큼 길어요. 한 소리를 두 박 이어서 연주해요.'},
{id:'whole',kind:'whole',symbol:svg('<ellipse cx="90" cy="65" rx="21" ry="13" fill="none" stroke="currentColor" stroke-width="6"/>'),question:'기둥이 없는 온음표예요. 몇 박일까요?',choices:['네 박','반 박','두 박'],answer:0,why:'온음표는 4분음표 네 개만큼 길어요. 이 퀴즈에서는 네 박 이어서 연주해요.'},
{id:'eighth',kind:'eighth',symbol:note(true,true),question:'꼬리가 하나 달린 8분음표. 길이는 얼마일까요?',choices:['두 박','반 박','네 박'],answer:1,why:'8분음표는 4분음표 길이의 절반이에요. 한 박을 똑같이 나눈 반 박이에요.'},
{id:'paired-eighths',kind:'paired-eighths',symbol:svg(head(48,80,true)+head(116,72,true)+'<path d="M61 78V26L129 18V70" fill="none" stroke="currentColor" stroke-width="5"/><path d="M61 27L129 19" stroke="currentColor" stroke-width="9"/>'),question:'연결된 8분음표 두 개를 합치면 몇 박일까요?',choices:['두 박','한 박','네 박'],answer:1,why:'반 박과 반 박이 만나 한 박이 돼요. 음표 두 개의 길이를 모두 합쳐요.'},
{id:'rest',kind:'rest',symbol:svg('<path d="M98 18L79 41L99 55L80 77Q100 73 92 96" fill="none" stroke="currentColor" stroke-width="7" stroke-linejoin="round"/>'),question:'4분쉼표예요. 어떻게 할까요?',choices:['두 박 크게 연주해요','더 빨리 연주해요','한 박 소리를 쉬어요'],answer:2,why:'4분쉼표에서는 한 박 쉬어요. 소리는 쉬지만 속으로 박은 계속 세어요.'}
]);
export function drawMusicQuizBoard(ctx,index=0){const q=MUSIC_QUIZ[index]??MUSIC_QUIZ[0];ctx.fillStyle='#fff6df';ctx.fillRect(0,0,720,440);ctx.fillStyle='#365a4e';ctx.font='bold 42px sans-serif';ctx.textAlign='center';ctx.fillText('음표와 쉼표',360,58);ctx.font='24px sans-serif';ctx.fillText('4분음표 = 한 박',360,405);ctx.save();ctx.translate(360,230);ctx.strokeStyle='#bccabe';ctx.lineWidth=2;for(let i=-2;i<=2;i++){ctx.beginPath();ctx.moveTo(-255,i*26);ctx.lineTo(255,i*26);ctx.stroke();}ctx.strokeStyle='#365a4e';ctx.fillStyle='#365a4e';ctx.lineWidth=9;const ellipse=(x,y,filled)=>{ctx.beginPath();ctx.ellipse(x,y,31,20,-.3,0,Math.PI*2);filled?ctx.fill():ctx.stroke();};const stem=(x,y)=>{ctx.beginPath();ctx.moveTo(x+27,y-5);ctx.lineTo(x+27,y-120);ctx.stroke();};if(q.kind==='whole'){ellipse(0,0,false);}else if(q.kind==='rest'){ctx.beginPath();ctx.moveTo(14,-96);ctx.lineTo(-20,-45);ctx.lineTo(15,-10);ctx.lineTo(-17,39);ctx.quadraticCurveTo(29,32,8,83);ctx.stroke();}else if(q.kind==='paired-eighths'){ellipse(-75,27,true);ellipse(65,5,true);stem(-75,27);stem(65,5);ctx.lineWidth=17;ctx.beginPath();ctx.moveTo(-48,-90);ctx.lineTo(92,-112);ctx.stroke();}else{ellipse(-15,25,q.kind!=='half');stem(-15,25);if(q.kind==='eighth'){ctx.beginPath();ctx.moveTo(12,-95);ctx.quadraticCurveTo(88,-62,45,-20);ctx.stroke();}}ctx.restore();}
export function createMusicQuizState(){let index=0,selected=null,done=false;return{get question(){return MUSIC_QUIZ[index];},choose(i){if(done||!Number.isInteger(i)||i<0||i>=MUSIC_QUIZ[index].choices.length)return false;selected=i;return true;},retry(){if(done){index=0;done=false;}selected=null;},next(){if(done||selected===null)return false;if(index===MUSIC_QUIZ.length-1)done=true;else{index++;selected=null;}return true;},snapshot:()=>({index,selected,done,correct:selected!==null&&selected===MUSIC_QUIZ[index].answer})};}
export function openMusicQuiz(ui,{onQuestion=()=>{}}={}){const m=createMusicQuizState();return ui.workshop('벽의 음표 퀴즈',`<p class="caption">이 퀴즈에서는 4분음표를 한 박으로 세어요</p><p id="music-quiz-count"></p><div class="music-symbol" id="music-symbol"></div><h3 id="music-question"></h3><div class="music-choices" id="music-choices"></div><p class="learning-feedback" id="music-feedback" role="status"></p><div class="school-tool-row"><button id="music-retry">다시 생각하기</button><button class="primary" id="music-next" disabled>다음 음표</button></div>`,()=>{let alive=true;const $=id=>document.querySelector('#'+id);function render(){if(!alive)return;const s=m.snapshot(),q=m.question;onQuestion(s.index);$('music-quiz-count').textContent=`${s.index+1} / ${MUSIC_QUIZ.length}`;$('music-symbol').innerHTML=q.symbol;$('music-question').textContent=s.done?'여섯 가지 모양을 모두 살펴봤어요!':q.question;$('music-choices').replaceChildren();if(!s.done)for(const[i,label]of q.choices.entries()){const b=document.createElement('button');b.textContent=label;b.setAttribute('aria-pressed',String(s.selected===i));b.onclick=()=>{if(!alive)return;m.choose(i);render();};$('music-choices').append(b);}$('music-feedback').textContent=s.done?'피아노에서도 한 박과 두 박을 길이로 느껴 봐요':s.selected===null?'모양을 보고 골라요. 틀려도 다시 해 볼 수 있어요':(s.correct?'맞아요! ':'다시 살펴볼까요? ')+q.why;$('music-retry').textContent=s.done?'처음부터 다시':'다시 생각하기';$('music-next').hidden=s.done;$('music-next').disabled=s.selected===null;$('music-next').textContent=s.index===MUSIC_QUIZ.length-1?'마치기':'다음 음표';}$('music-retry').onclick=()=>{if(!alive)return;m.retry();render();};$('music-next').onclick=()=>{if(alive&&m.next())render();};render();return()=>{if(!alive)return;alive=false;onQuestion(0);};});}
